import React, { useState } from 'react';
import './App.css';

const DUMMY_ONTOLOGIES = [
  {
    title: 'Gene Ontology',
    description: 'A major bioinformatics initiative to unify the representation of gene and gene product attributes across all species.',
    publisher: 'Gene Ontology Consortium',
    ranking: Math.random(),
  },
  {
    title: 'Friend of a Friend (FOAF)',
    description: 'A project aimed at creating a Web of machine-readable pages describing people, the links between them and the things they create and do.',
    publisher: 'FOAF Project',
    ranking: Math.random(),
  },
  {
    title: 'Dublin Core',
    description: 'A set of vocabulary terms which can be used to describe resources for the purposes of discovery.',
    publisher: 'Dublin Core Metadata Initiative',
    ranking: Math.random(),
  },
  {
    title: 'Schema.org',
    description: 'A collaborative, community activity with a mission to create, maintain, and promote schemas for structured data on the Internet.',
    publisher: 'Schema.org',
    ranking: Math.random(),
  },
  {
    title: 'Simple Knowledge Organization System (SKOS)',
    description: 'A common data model for sharing and linking knowledge organization systems via the Web.',
    publisher: 'W3C',
    ranking: Math.random(),
  },
];

function fuzzyMatch(query, text) {
  return text.toLowerCase().includes(query.toLowerCase());
}

function App() {
  const [search, setSearch] = useState('');
  const [submittedQuery, setSubmittedQuery] = useState('');

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      setSubmittedQuery(search);
    }
  };

  const filtered = DUMMY_ONTOLOGIES.filter(onto =>
    fuzzyMatch(submittedQuery, onto.title) ||
    fuzzyMatch(submittedQuery, onto.description) ||
    fuzzyMatch(submittedQuery, onto.publisher)
  );

  return (
    <div className="app-container">
      <header>
        <h1>The Smeantic Registry</h1>
        <p>Search for semantic ontologies</p>
      </header>
      <div className="search-bar">
        <input
          type="text"
          placeholder="Search ontologies..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          onKeyDown={handleKeyDown}
        />
      </div>
      {submittedQuery && (
        <div className="results">
          {filtered.length === 0 ? (
            <p className="no-results">No ontologies found.</p>
          ) : (
            filtered.map((onto, idx) => (
              <div className="ontology-card" key={idx}>
                <h2>{onto.title}</h2>
                <p className="description">{onto.description}</p>
                <div className="meta">
                  <span className="publisher">Publisher: {onto.publisher}</span>
                  <span className="ranking">Ranking: {onto.ranking.toFixed(3)}</span>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

export default App;
